function icon(name,extraClass=''){const key=Object.hasOwn(ICON_PATHS,name)?name:'help-circle';const classes=String(extraClass).replace(/[^a-zA-Z0-9 _-]/g,'');return `<svg class="icon icon-${key}${classes?' '+classes:''}" data-icon="${key}" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">${ICON_PATHS[key]}</svg>`}
function heartIcon(on){return icon('heart',on?'is-filled':'')}
function categoryIcon(index){return icon(['apartment','house','briefcase','land','clock'][index]||'map')}
function mountHeaderIcons(){const nav=document.querySelector('header nav');if(!nav)return;const names=['map','apartment','heart','users','plus'];nav.querySelectorAll('a').forEach((link,index)=>{if(!link.querySelector('.icon'))link.insertAdjacentHTML('afterbegin',icon(names[index]||'map'))});const agent=document.querySelector('.account>a');if(agent&&!agent.querySelector('.icon'))agent.insertAdjacentHTML('afterbegin',icon('briefcase'));const menu=document.querySelector('header>.mobile');if(menu)menu.innerHTML=icon('menu');const lookup=document.querySelector('.footer-lookup');if(lookup){const submit=lookup.querySelector('button:not([type])');if(submit)submit.innerHTML=icon('search')+' Хайх';const top=lookup.querySelector('button[type="button"]');if(top)top.innerHTML=icon('arrow-up')+' Дээш'}}
